(()=>{'use strict';
 const money=n=>(n/100).toLocaleString('ru-RU')+' ₽',node=(tag,text)=>{const n=document.createElement(tag);n.textContent=text;return n;};
 const id=()=>crypto.randomUUID();
 async function api(path,body){const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),15000);try{const r=await fetch('/api/admin/workforce/'+path,{cache:'no-store',signal:controller.signal,...(body?{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)}:{})});const d=await r.json();if(!r.ok)throw Object.assign(Error(d.error),d);return d;}catch(e){if(e.name==='AbortError'||e instanceof TypeError)throw Error('Нет подтверждения сервера. Повторите действие: запись не продублируется.');throw e;}finally{clearTimeout(timer);}}
 function modal(title){const d=document.createElement('dialog');d.className='day-desk-dialog';const h=node('h2',title),body=node('div',''),error=node('p',''),close=node('button','Закрыть');error.className='work-error';error.setAttribute('role','status');close.type='button';close.onclick=()=>d.close();d.append(h,body,error,close);document.body.append(d);d.onclose=()=>d.remove();d.addEventListener('cancel',e=>{if(close.disabled)e.preventDefault();});d.showModal();return {d,body,error,close};}
 function amount(body,label,value,negative=false){const l=node('label',label),input=document.createElement('input');input.type='text';input.inputMode='decimal';input.required=true;if(value!==undefined)input.value=String(value/100);l.append(input);body.append(l);queueMicrotask(()=>input.focus());return ()=>{const s=input.value.trim().replace(',','.');if(!(negative?/^-?\d+(\.\d{1,2})?$/:/^\d+(\.\d{1,2})?$/).test(s))throw Error('Укажите сумму в рублях, например 1500 или 1500,50.');const n=Math.round(Number(s)*100);if(!Number.isSafeInteger(n)||Math.abs(n)>100000000)throw Error('Проверьте сумму.');return n;};}
 function saveButton(m,label,fn){const b=node('button',label);b.type='button';b.className='primary';m.body.append(b);b.onclick=async()=>{if(b.disabled)return;b.disabled=true;m.close.disabled=true;m.error.textContent='';try{await fn();}catch(e){m.error.textContent=e.message||'Нет связи. Повторите действие.';}finally{b.disabled=false;m.close.disabled=false;}};return b;}
 async function start(userId){const current=await api('current');if(current.desk?.enabled&&!current.desk.canStart)throw Error('Начать новую смену можно с 08:00 по Москве.');const body={requestId:id(),...(userId?{userId}:{})};if(current.desk?.enabled&&current.desk.needsOpening){return new Promise(resolve=>{const m=modal('Начать рабочий день');m.body.append(node('p','Укажите, сколько наличных сейчас в кассе. Это остаток для размена, он не входит в выручку и зарплату. Можно указать 0.'));const read=amount(m.body,'Наличные на начало, ₽');let sent=false;saveButton(m,'Начать работу',async()=>{if(!sent){body.cashStartCents=read();sent=true;m.body.querySelector('input').disabled=true;}await api('start',body);document.dispatchEvent(new Event('station-updated'));m.d.close();resolve(true);});m.d.addEventListener('close',()=>resolve(false));});}await api('start',body);document.dispatchEvent(new Event('station-updated'));return true;}
 async function summary(day){const s=await api('day-summary'+(day?'?day='+encodeURIComponent(day):'')),m=modal('Итог дня · '+s.day);if(!s.shift){m.body.append(node('p','Рабочий день ещё не начат. Нажмите «Я на смене».'));return;}m.body.append(node('p','Начальный остаток: '+money(s.shift.cash_start_cents)));const rows=Array.isArray(s.withdrawals)?s.withdrawals:(s.withdrawals.items||[]);m.body.append(node('p','Изъятия: '+money(rows.filter(x=>!x.voided_at).reduce((n,x)=>n+x.amount_cents,0))+' · не вычитаются из выручки.'));
 if(s.shift.closed_at){if(s.automaticClose)m.body.append(node('p','День закрыт автоматически в 07:30 по Москве. Начисление за забытые смены ограничено 02:00. Выручка — по зарегистрированным продажам, без ручной сверки.'));m.body.append(node('p','Итог сохранён: '+money(s.shift.total_revenue_cents)),node('p','Работа после сохранения итога учитывается отдельно при следующей сверке.'));const slot=node('div','');m.body.append(slot);if(window.STARTPrint)window.STARTPrint.mountReport(slot,{shiftId:s.shift.id});return;}
 m.body.append(node('p','Выручка кафе и проката с учётом возвратов. Остаток на начало и изъятия сюда не входят.'));const read=amount(m.body,'Общая выручка за день, ₽',s.registeredCents,true);saveButton(m,'Проверить итог',async()=>{const body={shiftId:s.shift.id,totalRevenueCents:read()},p=await api('preview',body),c=p.calculation,v=modal('Проверить начисления');v.body.append(node('p','Выручка: '+money(c.revenue.cents)));if(c.revenue.after_close_cents)v.body.append(node('p','Включена работа после прошлого закрытия: '+money(c.revenue.after_close_cents)));if(c.revenue.cash_adjustment_cents)v.body.append(node('p','Разница с продажами: '+money(c.revenue.cash_adjustment_cents)+'. Бонус с разницы делится по отработанным часам.'));for(const e of c.employees)v.body.append(node('p',e.name+' — '+money(e.salary_cents)+(e.active?' · ещё на смене':'')));const payload={...body,previewHash:p.previewHash,requestId:id()};const b=saveButton(v,'Сохранить итог дня',async()=>{await api('day-close',payload);v.d.close();m.d.close();document.dispatchEvent(new Event('station-updated'));await summary(s.day);});if(c.employees.some(e=>e.active)||!c.employees.length||c.unallocated_bonus_cents){b.disabled=true;v.error.textContent='Сначала завершите смены сотрудников и проверьте, что все продажи относятся к их рабочему времени.';}});
 }
 async function withdrawal(){const s=await api('withdrawal-context');if(!s.shift)throw Error('Рабочий день ещё ни разу не открывали. Сначала нажмите «Я на смене».');const m=modal('Забрать деньги из кассы');m.body.append(node('p','Рабочий день: '+s.shift.day.split('-').reverse().join('.')+(s.shift.closed_at?' · итог уже сохранён. Изъятие запишется отдельно, без изменения выручки и зарплаты.':'. Изъятие не уменьшает выручку и зарплату.')));const read=amount(m.body,'Сумма изъятия, ₽'),l=node('label','Комментарий · необязательно'),input=document.createElement('input');l.append(input);m.body.append(l);let payload;saveButton(m,'Сохранить изъятие',async()=>{if(!payload){const n=read();if(n<=0)throw Error('Сумма должна быть больше нуля.');payload={requestId:id(),shiftId:s.shift.id,amountCents:n,comment:input.value};m.body.querySelectorAll('input').forEach(x=>x.disabled=true);}await api('withdrawal',payload);m.d.close();document.dispatchEvent(new Event('station-updated'));});}
 async function opening(){const s=await api('day-summary');if(!s.shift||s.shift.closed_at)throw Error('Исправить остаток можно до сохранения итога дня.');const m=modal('Начальный остаток'),read=amount(m.body,'Наличные на начало, ₽',s.shift.cash_start_cents);saveButton(m,'Сохранить остаток',async()=>{await api('opening-balance',{shiftId:s.shift.id,expectedCashStartCents:s.shift.cash_start_cents,cashStartCents:read()});m.d.close();});}
 function last(){const m=modal('Вы последний завершили смену');m.body.append(node('p','Можно сейчас проверить выручку и начисления за день.'));m.close.textContent='Позже';saveButton(m,'Подвести итог дня',async()=>{m.d.close();await summary();});}
 window.STARTWork={start,summary,withdrawal,opening,last};
})();
